const moves=[
 {name:'Golpe',power:8,kind:'physical'},
 {name:'Pulso',power:11,kind:'arcane'},
 {name:'Guardia',power:0,kind:'guard'}
];

let state={
 seed:Math.floor(Math.random()*999999), day:1, time:8*60, coins:120,
 player:{x:15,y:15}, party:[], box:[], items:{capsules:8,herbs:3},
 inventory:{wood:0,stone:0,crystal:0}, nursery:[], discovered:[],
 mapW:90,mapH:60, settings:{music:true,sfx:true,volume:.7}, base:{x:15,y:15}
};
let map=[], encounterCooldown=0, keys={}, moving=false, battleState=null, audio=null;

function makeCreature(s,level=rand(2,6)){
 const max=s.hp+level*3, c={uid:crypto.randomUUID?crypto.randomUUID():Date.now()+Math.random(),sid:s.id,name:s.name,type:s.type,level,maxHp:max,hp:max,atk:s.atk+level*2,def:s.def+level,spd:s.spd+level,exp:0,affinity:rand(10,30),gender:Math.random()<.5?'L':'F',trait:pick(['Calm','Bold','Lively','Gentle']),};
 if(!state.discovered.includes(c.sid))state.discovered.push(c.sid);
 return c;
}
function speciesOf(c){return species.find(s=>s.id===c.sid)||species[0]}

function noise(n=1){if(!state.settings.sfx)return;if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=n;g.gain.value=.035*state.settings.volume;o.connect(g);g.connect(audio.destination);o.start();o.frequency.exponentialRampToValueAtTime(n*1.7,audio.currentTime+.08);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.stop(audio.currentTime+.13)}
function musicTick(){if(!state.settings.music)return;if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=pick([196,220,247,294,330]);g.gain.value=.008*state.settings.volume;o.connect(g);g.connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.45);o.stop(audio.currentTime+.5)}
setInterval(()=>{if(!document.hidden&&state.settings.music)musicTick()},1200);

function save(){localStorage.setItem(SAVE,JSON.stringify(state));toast('Partida guardada.');noise(440)}
function load(){try{const s=JSON.parse(localStorage.getItem(SAVE));if(s){state=Object.assign(state,s);return true}}catch(e){}return false}

function generateWorld(){
 const rng=x=>{x=(x+0x6D2B79F5)|0;let t=Math.imul(x^x>>>15,1|x);t^=t+Math.imul(t^t>>>7,61|t);return ((t^t>>>14)>>>0)/4294967296};
 let r=state.seed,map2=[];
 for(let y=0;y<state.mapH;y++){map2[y]=[];for(let x=0;x<state.mapW;x++){
   let v=rng(r+x*17+y*31), edge=x<2||y<2||x>state.mapW-3||y>state.mapH-3;
   let tile=v<.10?'water':v<.18?'sand':v<.30?'forest':v<.37?'rock':'grass';
   if(edge)tile='rock'; map2[y][x]=tile;
 }}
 // roads and home clearing
 for(let x=5;x<45;x++)map2[15][x]='path';
 for(let y=8;y<30;y++)map2[y][15]='path';
 for(let y=12;y<19;y++)for(let x=12;x<19;x++)map2[y][x]='home';
 map2[15][15]='home';
 return map2;
}
function isWalkable(x,y){let t=map[y]?.[x];return t&&t!=='water'&&t!=='rock'}
function initGame(fresh=false){
 if(fresh){state.seed=Math.floor(Math.random()*999999);state.day=1;state.time=8*60;state.coins=120;state.player={x:15,y:15};state.party=[makeCreature(species[0],5)];state.box=[];state.nursery=[];state.discovered=[];state.inventory={wood:0,stone:0,crystal:0};state.items={capsules:8,herbs:3};}
 map=generateWorld(); $('titleScreen').classList.add('hidden');$('hud').classList.remove('hidden');updateHUD(); render();
}
function tileColor(t){
 return {grass:'#3f7650',forest:'#2f6047',water:'#326a89',sand:'#b99762',rock:'#535968',path:'#8c795f',home:'#745e73'}[t]||'#304050'
}
function drawTile(x,y,t){
 ctx.fillStyle=tileColor(t);ctx.fillRect(x*T,y*T,T,T);
 ctx.fillStyle='rgba(255,255,255,.045)';ctx.fillRect(x*T,y*T+T-3,T,3);
 if(t==='grass'){ctx.fillStyle='#5b9860';for(let i=0;i<3;i++){let q=(x*17+y*13+i*9)%27;ctx.fillRect(x*T+q%26,y*T+(q*3)%28,2,5)}}
 if(t==='forest'){ctx.fillStyle='#183e31';ctx.fillRect(x*T+8,y*T+10,16,16);ctx.fillStyle='#356b43';ctx.fillRect(x*T+4,y*T+6,24,12);ctx.fillStyle='#7c5839';ctx.fillRect(x*T+14,y*T+19,5,11)}
 if(t==='water'){ctx.fillStyle='#6cc3d5';ctx.fillRect(x*T+5,y*T+11,13,2);ctx.fillRect(x*T+16,y*T+22,11,2)}
 if(t==='rock'){ctx.fillStyle='#737887';ctx.fillRect(x*T+7,y*T+8,18,18);ctx.fillStyle='#999da8';ctx.fillRect(x*T+10,y*T+6,9,7)}
 if(t==='home'){ctx.fillStyle='#aa8d69';ctx.fillRect(x*T+4,y*T+7,24,19);ctx.fillStyle='#cf685f';ctx.fillRect(x*T+2,y*T+3,28,7)}
}
function drawPlayer(){
 const x=state.player.x*T,y=state.player.y*T;ctx.fillStyle='#171b2a';ctx.fillRect(x+10,y+12,13,17);ctx.fillStyle='#e7a77c';ctx.fillRect(x+9,y+4,15,12);ctx.fillStyle='#4f73c4';ctx.fillRect(x+8,y+16,17,6);ctx.fillStyle='#25283a';ctx.fillRect(x+9,y+27,5,5);ctx.fillRect(x+19,y+27,5,5);
}
function drawWorldCreature(){
 if(!state.party[0])return;let c=state.party[0],x=state.player.x*T-10,y=state.player.y*T+20;ctx.fillStyle=speciesOf(c).color;ctx.fillRect(x,y,20,10);ctx.fillStyle=speciesOf(c).accent;ctx.fillRect(x+13,y+2,5,4)
}
function render(){
 ctx.clearRect(0,0,W,H);
 const viewW=Math.ceil(W/T)+2,viewH=Math.ceil(H/T)+2,ox=state.player.x-Math.floor(viewW/2),oy=state.player.y-Math.floor(viewH/2);
 for(let sy=0;sy<viewH;sy++)for(let sx=0;sx<viewW;sx++){let x=ox+sx,y=oy+sy;if(map[y]?.[x])drawTile(sx,sy,map[y][x]);}
 // landmarks
 const bx=15-ox,by=15-oy;if(bx>=0&&by>=0){ctx.fillStyle='#d5c4a1';ctx.fillRect(bx*T+9,by*T+8,14,18);ctx.fillStyle='#a95055';ctx.fillRect(bx*T+6,by*T+4,20,7)}
 const px=state.player.x-ox,py=state.player.y-oy;
 if(state.party[0]){let s=speciesOf(state.party[0]);ctx.fillStyle=s.color;ctx.fillRect(px*T-3,py*T+19,21,9);ctx.fillStyle=s.accent;ctx.fillRect(px*T+12,py*T+21,5,4)}
 drawPlayerAt(px*T,py*T);
 // day/night
 const phase=(state.time/1440);let alpha=phase<.25?0.28:phase<.75?0:0.20;ctx.fillStyle=`rgba(12,20,55,${alpha})`;ctx.fillRect(0,0,W,H);
 ctx.fillStyle='#ffffffb0';ctx.font='10px monospace';ctx.fillText(`AETHERWILDS  •  ${state.player.x},${state.player.y}`,12,H-12);
}
function drawPlayerAt(x,y){ctx.fillStyle='#171b2a';ctx.fillRect(x-6,y-4,13,17);ctx.fillStyle='#e7a77c';ctx.fillRect(x-7,y-12,15,12);ctx.fillStyle='#4f73c4';ctx.fillRect(x-8,y,17,6);ctx.fillStyle='#25283a';ctx.fillRect(x-7,y+13,5,5);ctx.fillRect(x+2,y+13,5,5)}

function move(dx,dy){
 if(battleState)return;let nx=state.player.x+dx,ny=state.player.y+dy;
 if(isWalkable(nx,ny)){state.player.x=nx;state.player.y=ny;state.time=(state.time+2)%1440;encounterCooldown--;noise(190);if(encounterCooldown<=0&&['grass','forest'].includes(map[ny][nx])&&Math.random()<.16){encounterCooldown=7;startWildBattle()}render();updateHUD()}
}
function updateHUD(){
 let h=Math.floor(state.time/60),m=String(state.time%60).padStart(2,'0');$('dayLabel').textContent=`Día ${state.day} · ${String(h).padStart(2,'0')}:${m}`;$('coins').textContent=`◈ ${state.coins}`;
 $('partyMini').innerHTML=state.party.slice(0,6).map(c=>`<div class="partyDot" title="${c.name} Nv.${c.level}">${speciesOf(c).name.slice(0,2).toUpperCase()}</div>`).join('');
}

function startWildBattle(){
 const s=pick(species.filter(s=>Math.random()<s.rarity/60))||species[0];let wild=makeCreature(s,Math.max(2,Math.floor(state.player.x/8)+rand(0,4)));
 battleState={wild,player:state.party[0],guard:false};$('battle').classList.remove('hidden');$('battleLog').textContent=`¡${wild.name} salvaje apareció!`;drawBattle();noise(520)
}
function drawCreature(c,canvas,flip=false){
 canvas.width=120;canvas.height=100;let x=canvas.getContext('2d');x.imageSmoothingEnabled=false;let s=speciesOf(c),col=s.color,ac=s.accent;x.clearRect(0,0,120,100);
 x.fillStyle='rgba(0,0,0,.25)';x.fillRect(22,76,76,8);
 x.fillStyle=col;
 if(s.shape==='seed'){x.fillRect(42,30,38,42);x.fillRect(35,42,10,20);x.fillRect(75,42,10,20);x.fillRect(49,20,20,14)}
 if(s.shape==='fox'){x.fillRect(34,37,52,35);x.fillRect(26,26,17,25);x.fillRect(77,27,17,24);x.fillRect(25,62,18,12);x.fillRect(77,62,18,12)}
 if(s.shape==='bird'){x.fillRect(40,32,40,40);x.fillRect(25,45,25,17);x.fillRect(70,45,25,17);x.fillRect(52,21,15,15)}
 if(s.shape==='horn'){x.fillRect(36,31,50,43);x.fillRect(27,42,14,22);x.fillRect(81,42,14,22);x.fillRect(48,19,8,17);x.fillRect(64,15,8,22)}
 if(s.shape==='bug'){x.fillRect(42,29,38,45);x.fillRect(31,39,12,28);x.fillRect(77,39,12,28);x.fillRect(52,20,6,12);x.fillRect(65,20,6,12)}
 if(s.shape==='turtle'){x.fillRect(32,27,56,48);x.fillRect(23,40,18,24);x.fillRect(79,40,18,24);x.fillRect(43,65,11,12);x.fillRect(66,65,11,12)}
 if(s.shape==='deer'){x.fillRect(38,30,45,40);x.fillRect(27,41,16,20);x.fillRect(78,41,16,20);x.fillRect(47,17,8,18);x.fillRect(66,14,8,21)}
 if(s.shape==='bat'){x.fillRect(43,35,35,40);x.fillRect(18,31,30,26);x.fillRect(72,31,30,26)}
 x.fillStyle=ac;x.fillRect(51,40,7,7);x.fillRect(66,40,7,7);x.fillStyle='#1c2030';x.fillRect(53,42,3,3);x.fillRect(68,42,3,3);
}
function drawBattle(){
 let w=$('battleWild'),p=$('battlePlayer');w.innerHTML='<canvas></canvas>';p.innerHTML='<canvas></canvas>';drawCreature(battleState.wild,w.querySelector('canvas'));drawCreature(battleState.player,p.querySelector('canvas'));
 let b=battleState; $('battleInfo').innerHTML=`<div class="statBox"><b>${b.wild.name}</b> Nv.${b.wild.level}<div class="hpbar"><i style="width:${b.wild.hp/b.wild.maxHp*100}%"></i></div></div><div class="statBox"><b>${b.player.name}</b> Nv.${b.player.level}<div class="hpbar"><i style="width:${b.player.hp/b.player.maxHp*100}%"></i></div></div>`;
}
function battleText(t){$('battleLog').textContent=t}
function damage(att,def,power){return Math.max(1,Math.floor(power+att.atk*.55-def.def*.28+rand(-2,3)))}
function battleAction(a){
 if(!battleState)return;let b=battleState;
 if(a==='run'){battleText('Escapas antes de que la criatura cierre el paso.');noise(160);return setTimeout(endBattle,450)}
 if(a==='capture'){
   if(state.items.capsules<=0)return battleText('No te quedan cápsulas de vínculo.');
   state.items.capsules--;let chance=.28+(1-b.wild.hp/b.wild.maxHp)*.62+b.player.affinity*.002;
   if(Math.random()<chance){state.box.push(b.wild);state.coins+=12;battleText(`¡${b.wild.name} se une a tu colección!`);noise(760);setTimeout(endBattle,800);return}
   battleText('La cápsula vibra... ¡pero se rompe el vínculo!');noise(240);
 } else if(a==='bond'){
   b.player.affinity=clamp(b.player.affinity+rand(3,8),0,100);b.player.hp=clamp(b.player.hp+5,0,b.player.maxHp);battleText(`${b.player.name} siente tu confianza. Afinidad +${rand(3,8)}.`);noise(390);
 } else {
   let d=damage(b.player,b.wild,moves[a==='strike'?0:1].power);b.wild.hp-=d;b.player.exp+=d;b.player.affinity=clamp(b.player.affinity+1,0,100);battleText(`${b.player.name} inflige ${d} de daño.`);
   if(b.wild.hp<=0){state.coins+=8;b.player.level+=1;b.player.maxHp+=3;b.player.hp=b.player.maxHp;b.player.atk+=1;b.player.def+=1;b.player.spd+=1;battleText(`${b.wild.name} cae. ${b.player.name} sube a Nv.${b.player.level}.`);noise(880);setTimeout(endBattle,900);updateHUD();return}
 }
 setTimeout(enemyTurn,420);drawBattle();
}
function enemyTurn(){if(!battleState)return;let b=battleState,d=damage(b.wild,b.player,rand(6,12));b.player.hp-=d;battleText(`${b.wild.name} responde e inflige ${d}.`);if(b.player.hp<=0){b.player.hp=Math.ceil(b.player.maxHp*.35);battleText(`${b.player.name} queda debilitado. Te retiras al refugio.`);setTimeout(endBattle,900)}drawBattle()}
function endBattle(){$('battle').classList.add('hidden');battleState=null;updateHUD();render();save()}

function openPanel(name){
 $('menu').classList.add('hidden');$('subpanel').classList.remove('hidden');let title='',html='';
 if(name==='creatures'){title='CRIATURAS';html='<div class="cardGrid">'+state.party.concat(state.box).map((c,i)=>`<div class="creatureCard"><strong>${speciesOf(c).name}</strong><span>${c.type} · Nv.${c.level} · ${c.gender}</span><div>HP ${c.hp}/${c.maxHp}</div><div class="bar"><i style="width:${c.hp/c.maxHp*100}%"></i></div><small>Afinidad ${c.affinity}% · ${c.trait}</small></div>`).join('')+'</div>'}
 if(name==='nursery'){title='CRIADERO';html=`<p>Deja dos criaturas compatibles y, tras un rato de aventura, descubrirás una cría con rasgos heredados.</p><div class="row"><span>Plazas: ${state.nursery.length}/2</span><button id="breedBtn">CRIAR</button></div><div class="cardGrid">${state.nursery.map(c=>`<div class="creatureCard"><strong>${c.name}</strong><small>${c.type} · Afinidad ${c.affinity}%</small></div>`).join('')}</div><p class="hint">Para probarlo, primero coloca dos criaturas desde tu colección. La demo permite usar las dos primeras.</p><button id="nurseryAuto" class="bigBtn">USAR MIS DOS PRIMERAS</button>`}
 if(name==='inventory'){title='MOCHILA';html=`<div class="row"><span>◈ Cápsulas de vínculo</span><b>${state.items.capsules}</b></div><div class="row"><span>✚ Hierbas</span><b>${state.items.herbs}</b></div><div class="row"><span>▣ Madera</span><b>${state.inventory.wood}</b></div><div class="row"><span>◆ Piedra</span><b>${state.inventory.stone}</b></div><div class="row"><span>✦ Cristal</span><b>${state.inventory.crystal}</b></div>`}
 if(name==='map'){title='MAPA';html=`<p>La región se genera con tu semilla <b>${state.seed}</b>. Las zonas cambian entre partidas.</p><div class="row"><span>Posición</span><b>${state.player.x}, ${state.player.y}</b></div><div class="row"><span>Bioma actual</span><b>${map[state.player.y][state.player.x]}</b></div><div class="row"><span>Especies descubiertas</span><b>${state.discovered.length}/${species.length}</b></div>`}
 if(name==='settings'){title='AJUSTES';html=`<div class="row"><span>Música</span><button id="musicToggle">${state.settings.music?'ACTIVADA':'DESACTIVADA'}</button></div><div class="row"><span>Efectos</span><button id="sfxToggle">${state.settings.sfx?'ACTIVADOS':'DESACTIVADOS'}</button></div><div class="row"><span>Volumen</span><input id="volume" type="range" min="0" max="1" step=".05" value="${state.settings.volume}"></div><div class="row"><span>Pantalla</span><button id="fullscreenBtn">PANTALLA COMPLETA</button></div>`}
 $('subTitle').textContent=title;$('subContent').innerHTML=html;
 if(name==='settings'){$('musicToggle').onclick=()=>{state.settings.music=!state.settings.music;openPanel('settings')};$('sfxToggle').onclick=()=>{state.settings.sfx=!state.settings.sfx;openPanel('settings')};$('volume').oninput=e=>state.settings.volume=+e.target.value;$('fullscreenBtn').onclick=()=>document.documentElement.requestFullscreen?.()}
 if(name==='nursery'){$('nurseryAuto').onclick=()=>{if(state.party.length>=2){state.nursery=[state.party[0],state.party[1]];toast('Dos criaturas han entrado al criadero.');openPanel('nursery')}};$('breedBtn').onclick=breed}
}
function breed(){
 if(state.nursery.length<2)return toast('Necesitas dos criaturas.');
 let a=state.nursery[0],b=state.nursery[1];if(a.sid!==b.sid)return toast('En esta demo, las dos criaturas deben ser de la misma especie.');
 let s=speciesOf(a),baby=makeCreature(s,1);baby.maxHp=Math.round((a.maxHp+b.maxHp)/2);baby.hp=baby.maxHp;baby.affinity=20;state.box.push(baby);state.nursery=[];state.coins=Math.max(0,state.coins-15);toast(`¡Ha nacido un ${baby.name}!`);openPanel('nursery');noise(700)
}
function toast(t){let e=$('toast');e.textContent=t;e.classList.add('toastOn');clearTimeout(window._toast);window._toast=setTimeout(()=>e.classList.remove('toastOn'),1700)}

document.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(e.key.toLowerCase()))e.preventDefault();if(e.key.toLowerCase()==='m'){$('menu').classList.toggle('hidden');}if(e.key.toLowerCase()==='e')interact()});
document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
let lastMove=0;function loop(t){if(!battleState&&Date.now()-lastMove>125){let dx=0,dy=0;if(keys.w||keys.arrowup)dy=-1;else if(keys.s||keys.arrowdown)dy=1;else if(keys.a||keys.arrowleft)dx=-1;else if(keys.d||keys.arrowright)dx=1;if(dx||dy){move(dx,dy);lastMove=Date.now()}}requestAnimationFrame(loop)}requestAnimationFrame(loop);
function interact(){if(battleState)return;let t=map[state.player.y][state.player.x];if(t==='home'){state.party.forEach(c=>c.hp=c.maxHp);toast('Descansas en tu refugio. Equipo recuperado.');noise(520)}else{state.inventory[pick(['wood','stone','crystal'])]++;toast('Encuentras un recurso en el terreno.');noise(320)}}

document.querySelectorAll('[data-dir]').forEach(b=>b.addEventListener('pointerdown',e=>{let d=b.dataset.dir;move(d==='left'?-1:d==='right'?1:0,d==='up'?-1:d==='down'?1:0)}));
$('touchInteract').onclick=interact;$('touchMenu').onclick=()=>$('menu').classList.toggle('hidden');
$('menuBtn').onclick=()=>$('menu').classList.remove('hidden');
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).classList.add('hidden'));
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openPanel(b.dataset.open));
$('saveBtn').onclick=save;
document.querySelectorAll('.battleBtn').forEach(b=>b.onclick=()=>battleAction(b.dataset.action));
$('newGame').onclick=()=>{localStorage.removeItem(SAVE);initGame(true);noise(440)};
$('continueGame').onclick=()=>{if(load())initGame(false);else toast('No hay partida guardada.')};

if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
if(load()){ /* title remains, continue available */ } else {$('continueGame').style.opacity=.45}
